style.css:
@-moz-document domain("youtube.com") {
.ytp-play-progress {
    background: linear-gradient(
        to right,
        #450008,
        #8b0018,
        #c45b69,
        #ffffff
    ) !important;
}

.ytp-scrubber-button {
    background: url("https://i.postimg.cc/x1rCYq0f/download.png") center / contain no-repeat !important;
    width: 55px !important;
    height: 55px !important;
    box-shadow: none !important;
    transform: translateY(-33px) !important;
}
}
